"""v3 单文件研究者视图：只显示真实节点，未运行候选明确标记。"""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def write_tree_page(output: dict[str, Any], path: Path) -> None:
    data = {k: output.get(k) for k in ("mode", "status", "counts", "search_config", "statistics")}
    data["experiments"] = []
    for experiment in output["experiments"]:
        runs = {}
        for run_id, record in experiment["runs"].items():
            item = {k: v for k, v in record.items() if k not in ("model_calls", "events", "final_state", "initial_state", "private_contexts")}
            timeline = record.get("timeline_id", record.get("depth", 0) + 1)
            item["events"] = [e for e in record.get("events", []) if e["timeline_id"] == timeline and e["kind"] != "reset"]
            item["call_count"] = len(record.get("model_calls", []))
            runs[run_id] = item
        data["experiments"].append({**{k: v for k, v in experiment.items() if k != "runs"}, "runs": runs})
    payload = json.dumps(data, ensure_ascii=False, allow_nan=False)
    for a, b in (("<", "\\u003c"), (">", "\\u003e"), ("&", "\\u0026"), ("\u2028", "\\u2028"), ("\u2029", "\\u2029")):
        payload = payload.replace(a, b)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(_PAGE.replace("__DATA__", payload), encoding="utf-8")


_PAGE = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>SocialRewind v3 · 社会策略树</title><style>
:root{font:15px/1.65 system-ui,sans-serif;color:#e5edf7;background:#0c1423;color-scheme:dark}*{box-sizing:border-box}body{margin:0}main{max-width:1550px;padding:30px 24px;margin:auto}h1{font-size:32px;margin:0}h2{font-size:20px}h3{font-size:16px}p{margin:7px 0 15px}.tag,.accent{color:#7fe1cd}.muted{color:#a7b9d0}.notice{border-left:3px solid #7fe1cd;background:#142538;padding:12px 16px}
.toolbar{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin:20px 0}select,button{font:inherit;color:inherit;border:1px solid #405777;border-radius:8px;background:#19283e;padding:8px 12px;cursor:pointer}button:hover{background:#233b55}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #7fe1cd}input[type=range]{min-width:150px}
.grid{display:grid;grid-template-columns:minmax(320px,0.85fr) minmax(0,1.4fr);gap:22px;align-items:start}.panel{background:#111f32;border:1px solid #31445f;border-radius:13px;padding:18px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;margin:16px 0;font-size:14px}th,td{padding:9px 12px;white-space:nowrap;border-bottom:1px solid #31445f;text-align:left}th{color:#9edfd4}
ul.tree,ul.tree ul{list-style:none;padding-left:22px;margin:10px 0}ul.tree{padding-left:0}ul.tree ul{border-left:1px solid #45617f}ul.tree li{position:relative;padding:8px 0 8px 10px}ul.tree ul>li:before{position:absolute;content:'';height:1px;width:10px;background:#45617f;left:0;top:30px}
.node{display:block;text-align:left;width:100%;font-size:14px;border-left:4px solid #719cdb;overflow-wrap:anywhere}.node.deal{border-left-color:#7fe1cd}.node.failed{border-left-color:#ef929f}.node.selected{outline:2px solid #e4c07f}.node.onpath{background:#1a3a49}.candidate{display:block;border:1px dashed #45617f;color:#98aac1;padding:8px;border-radius:8px;font-size:12px}.legend{font-size:13px;color:#a7b9d0}.plan,.memory{padding:12px;background:#18313a;border-radius:8px;margin:12px 0}.event{border-left:3px solid #719cdb;border-radius:8px;padding:12px;background:#1b2d44;margin:12px 0}.event.seller{border-color:#7fe1cd;background:#18333a}.event.refused{border-color:#ef929f}.speech{white-space:pre-wrap;overflow-wrap:anywhere}.terms{color:#e2c68d;font-family:ui-monospace,monospace;font-size:13px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}details{margin:12px 0}summary{cursor:pointer}svg{display:block;width:100%;height:auto}.curve-panel{margin:20px 0}.label{font-size:12px;fill:#a7b9d0}footer{font-size:13px;color:#a7b9d0;margin-top:24px}@media(max-width:850px){.grid{grid-template-columns:1fr}main{padding:20px 14px}h1{font-size:27px}}
</style></head><body><main><div class="tag">THE WORLD RESETS. STRATEGIES BRANCH.</div><h1>SocialRewind v3 / 社会策略树</h1>
<p class="muted">同一 S₀ → 私人策略假设 → 完整谈判 → 客观结果 → 下一次搜索选择</p>
<p class="notice">研究者本地审计视图，含双方私人计划、决策与历史。只有价格、交付、保障三项可执行。未探索候选不代表发生过谈判；搜索最佳与独立重执行分开呈现。完整模型请求、响应与token用量见原始JSON。</p>
<p id="status" class="muted"></p><div id="comparison" class="scroll"></div>
<div class="toolbar"><label>重复 <select id="repeat"></select></label><label>方法 <select id="method"><option value="linear">Linear Rewind</option><option value="random">Random Branching</option><option value="guided" selected>Guided UCT</option></select></label><label>搜索进度 <input id="step" type="range" min="0" max="0" value="0"></label><span id="step-label"></span><button id="play">播放真实搜索过程</button></div>
<section class="panel curve-panel"><h2>Best-observed Welfare / 搜索次数</h2><div id="curve"></div><p class="muted">共享根为第0次；曲线只累计搜索观察，独立验证不进入曲线。技术失败不伪造福利值。</p></section>
<div class="grid"><section class="panel"><h2>真实父子树</h2><p class="legend">绿色边：成交；红色边：失败/中断；金框：当前查看；着色：本次扩展路径；虚线：尚未运行候选。</p><div id="tree"></div><h3>本次选择依据</h3><pre id="selection"></pre><details><summary>全部选择与回传记录</summary><pre id="search-audit"></pre></details></section>
<section id="detail" class="panel"></section></div>
<details><summary>跨重复汇总与配对结果（探索性）</summary><pre id="statistics"></pre></details>
<footer>这是有限预算 UCT-inspired 搜索，无训练网络。社会福利奖励仅用于研究者侧分配搜索预算，不注入 Agent。策略由两个LLM分别生成；计划、措辞或报价变化不自动证明新的社会策略。v2与v3场景不同，不直接归因比较。</footer>
</main><script type="application/json" id="data">__DATA__</script><script>
'use strict';const data=JSON.parse(document.getElementById('data').textContent),rep=document.getElementById('repeat'),method=document.getElementById('method'),step=document.getElementById('step');const names={linear:'Linear',random:'Random',guided:'Guided'};let selected='n0',timer=null;
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}function json(v){return JSON.stringify(v,null,2)}function terms(t){return t?`${t.price}元 / ${t.delivery_days}天交付 / ${t.warranty_days}天保障`:'未成交';}function exp(){return data.experiments[Number(rep.value)]}function meta(){return exp().methods[method.value]}function tree(){return meta()?.tree??{nodes:[{node_id:'n0',parent_id:null,depth:0,branch_mode:'natural',run_id:'root',status:exp().runs.root?.status}],selections:[],backprop:[],best_curve:[]}}
function comparison(){
 const box=document.getElementById('comparison');box.replaceChildren();const table=el('table'),head=el('tr');
 ['方法','启动/预算（尝试）','已结算 / 技术失败','成交率','平均 Buyer / Seller','平均福利','Pareto / 平均轮数','搜索最佳福利','独立验证福利','验证 Buyer / Seller','额外调用 / token'].forEach(t=>head.append(el('th',t)));table.append(head);
 for(const m of ['linear','random','guided']){const md=exp().methods[m],s=md?.statistics,v=md?.validation_run_id?exp().runs[md.validation_run_id]:null,tr=el('tr');
  const cells=[names[m],s?`${s.negotiations_started}/${data.search_config.max_nodes-1}（${s.additional_attempts}）`:'未执行',s?`${s.terminal_negotiations} / ${s.failed_attempts}`:'—',s?.agreement_rate!=null?`${(100*s.agreement_rate).toFixed(1)}%`:'—',s?`${s.buyer_utility?.toFixed(1)??'—'} / ${s.seller_utility?.toFixed(1)??'—'}`:'—',s?.social_welfare?.toFixed(1)??'—',s?`${s.pareto_efficient!=null?(100*s.pareto_efficient).toFixed(1)+'%':'—'} / ${s.rounds?.toFixed(1)??'—'}`:'—',s?.best_observed_welfare??'—',v?.metrics?.social_welfare??'未完成',v?.metrics?`${v.metrics.buyer_utility} / ${v.metrics.seller_utility}`:'—',s?`${s.additional_search_usage.calls} / ${s.additional_search_usage.total_tokens}`:'—'];
  cells.forEach(t=>tr.append(el('td',String(t))));table.append(tr);
 }box.append(table);box.append(el('p','表内搜索均值不含共享根；收益/福利/Pareto/轮数条件于有效结算。成交率分母为实际启动数；技术失败可与已结算重叠（如Reflection失败）。未完成启动预算项保留，但不进入主等预算配对。','muted'));
}
function curve(){
 const box=document.getElementById('curve');box.replaceChildren();const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 760 210');svg.setAttribute('aria-label','三方法搜索最佳福利曲线，独立验证不纳入');const colors={linear:'#e4c07f',random:'#719cdb',guided:'#7fe1cd'};const max=Math.max(1,...Object.values(exp().methods).flatMap(m=>m.tree.best_curve.map(p=>p.best_observed_welfare??0)));
 function text(x,y,s){const t=document.createElementNS(ns,'text');t.setAttribute('x',x);t.setAttribute('y',y);t.setAttribute('class','label');t.textContent=s;svg.append(t);return t;}
 text(610,15,'图例');
 for(const [m,md] of Object.entries(exp().methods)){
  const points=md.tree.best_curve.filter(p=>p.best_observed_welfare!==null);const line=document.createElementNS(ns,'polyline');line.setAttribute('points',points.map(p=>`${45+p.search_index*90},${165-135*p.best_observed_welfare/max}`).join(' '));line.setAttribute('stroke',colors[m]);line.setAttribute('fill','none');line.setAttribute('stroke-width',m===method.value?'4':'2');line.setAttribute('opacity',m===method.value?'1':'.55');svg.append(line);
  for(const p of points){const c=document.createElementNS(ns,'circle');c.setAttribute('cx',45+p.search_index*90);c.setAttribute('cy',165-135*p.best_observed_welfare/max);c.setAttribute('r','4');c.setAttribute('fill',colors[m]);const title=document.createElementNS(ns,'title');title.textContent=`${names[m]} 第${p.search_index}次：${p.best_observed_welfare}`;c.append(title);svg.append(c);}
  text(610,35+25*['linear','random','guided'].indexOf(m),names[m]).style.fill=colors[m];
 }
 for(let i=0;i<data.search_config.max_nodes;i++)text(42+i*90,190,String(i));text(5,30,max.toFixed(0));text(20,165,'0');box.append(svg);
}
function detail(node){const box=document.getElementById('detail');box.replaceChildren();const r=exp().runs[node.run_id];if(!r){box.append(el('p','尚无运行记录'));return;}box.append(el('h2',`${names[method.value]} ${node.node_id} · ${node.branch_mode} · ${r.status}`));if(r.error)box.append(el('pre',`${r.error_phase??r.phase}: ${json(r.error)}`));const parent=node.parent_id?tree().nodes.find(n=>n.node_id===node.parent_id):null,old=parent?exp().runs[parent.run_id]:null;
box.append(el('h3','本人路径与私人计划（彼此不可见）'));for(const role of ['buyer','seller']){const mem=el('div',undefined,'memory'),path=r.path_memories?.[role]??[];mem.append(el('strong',`${role} 来源：${path.map(p=>p.source_node_id).join(' → ')||'无前世记忆'}`));const p=r.plans?.[role];if(p){for(const [label,key] of [['已有依据','evidence'],['未验证假设','hypothesis'],['策略方向','strategy'],['预期观察','expected_observation'],['风险','risk']])mem.append(el('p',`${label}：${p[key]}`));}else mem.append(el('p',node.parent_id===null?'自然根节点，无预设策略计划。':'本角色计划未完成；失败原因见上方。'));const d=el('details');d.append(el('summary','查看本人授权历史与Reflection'));d.append(el('pre',json(path)));mem.append(d);box.append(mem);}
if(r.metrics){box.append(el('h3','实际合同与双方收益'));box.append(el('p',`${terms(r.metrics.deal_terms)}\nBuyer ${r.metrics.buyer_utility} / Seller ${r.metrics.seller_utility} / Welfare ${r.metrics.social_welfare} / ${r.metrics.rounds}轮`,'speech'));if(old?.metrics)box.append(el('p',`相较父节点：${terms(old.metrics.deal_terms)} → ${terms(r.metrics.deal_terms)}；福利变化 ${r.metrics.social_welfare-old.metrics.social_welfare}，买方变化 ${r.metrics.buyer_utility-old.metrics.buyer_utility}，卖方变化 ${r.metrics.seller_utility-old.metrics.seller_utility}。`,'muted'));}
box.append(el('h3','实际互动与被拒绝尝试 / 计划不固定行动'));for(const e of r.events??[]){const b=el('article',undefined,'event '+e.actor+(e.accepted?'':' refused'));b.append(el('small',`#${e.timeline_sequence} ${e.actor} ${e.kind}${e.accepted?'':' · 被拒绝，未发送给对方'}`));b.append(el('p',e.input.text??'','speech'));if(e.kind==='offer')b.append(el('div',terms(e.input),'terms'));if(e.input.offer_id)b.append(el('div','回应 '+e.input.offer_id,'terms'));const d=el('details');d.append(el('summary','显式决策说明 / 审计'));d.append(el('pre',json(e.decision)));b.append(d);box.append(b);}
const refl=el('details');refl.append(el('summary','本节点结束后的本人Reflection'));refl.append(el('pre',json(r.reflections)));box.append(refl);const validation=meta()?.validation_run_id?exp().runs[meta().validation_run_id]:null;if(meta()?.winner_id===node.node_id){box.append(el('h3','独立重执行验证（不参与搜索选择）'));box.append(el('p',validation?.metrics?`${terms(validation.metrics.deal_terms)}；Welfare ${validation.metrics.social_welfare}；Buyer ${validation.metrics.buyer_utility} / Seller ${validation.metrics.seller_utility}`:'验证未完成'));const d=el('details');d.append(el('summary','验证的独立实际对话与记录'));d.append(el('pre',json(validation)));box.append(d);}
const audit=el('details');audit.append(el('summary','原始节点审计记录'));audit.append(el('pre',json(r)));box.append(audit);}
function draw(){comparison();curve();const t=tree(),s=Number(step.value);document.getElementById('step-label').textContent=`第 ${s} 次 / 最多 ${data.search_config.max_nodes-1} 次后续搜索`;const visible=t.nodes.slice(0,s+1);if(!visible.some(n=>n.node_id===selected))selected=visible.at(-1)?.node_id??'n0';const chosen=t.selections[s-1],pathIds=new Set([chosen?.parent_id]);let p=visible.find(n=>n.node_id===chosen?.parent_id);while(p?.parent_id){pathIds.add(p.parent_id);p=visible.find(n=>n.node_id===p.parent_id);}const box=document.getElementById('tree');box.replaceChildren();function branch(n){const li=el('li'),r=exp().runs[n.run_id],b=el('button',`${n.node_id} · ${n.branch_mode}\n${r?.status??n.status} · ${r?.metrics?.deal?'成交':r?.metrics?'未成交':'未完成'} · W ${r?.metrics?.social_welfare??'—'}`,'node '+(r?.metrics?.deal?'deal':'')+(r?.status==='failed'||r?.status==='interrupted'?' failed':'')+(n.node_id===selected?' selected':'')+(pathIds.has(n.node_id)?' onpath':''));b.addEventListener('click',()=>{selected=n.node_id;draw();});li.append(b);const stats=[...(t.backprop??[])].slice(0,s+1).flatMap(p=>p.updates).filter(u=>u.node_id===n.node_id).at(-1);li.append(el('small',stats?`N=${stats.visits}, Q=${stats.value_sum.toFixed(3)}, attempts=${stats.attempts}`:'尚未回传','muted'));const children=visible.filter(c=>c.parent_id===n.node_id),ul=el('ul');children.forEach(c=>ul.append(branch(c)));const depthLimit=method.value==='linear'?data.search_config.max_nodes-1:data.search_config.max_depth;if(r?.status==='completed'&&n.depth<depthLimit&&visible.length<data.search_config.max_nodes){const modes=method.value==='linear'?(children.length?[]:[(n.depth%2)?'exploration':'exploitation']):['exploitation','exploration'].filter(m=>!children.some(c=>c.branch_mode===m));modes.forEach(m=>{const q=el('li');q.append(el('span',`${m} · 未探索候选（未运行）`,'candidate'));ul.append(q);});}if(ul.children.length)li.append(ul);return li;}const ul=el('ul',undefined,'tree');if(visible[0])ul.append(branch(visible[0]));box.append(ul);document.getElementById('selection').textContent=chosen?json(chosen):'共享自然根：没有策略计划或搜索选择。';document.getElementById('search-audit').textContent=json({selections:t.selections,backprop:t.backprop});detail(visible.find(n=>n.node_id===selected)??visible[0]);}
function reset(){const t=tree();step.max=String(Math.max(0,t.nodes.length-1));step.value=step.max;selected=t.nodes.at(-1)?.node_id??'n0';draw();}
data.experiments.forEach((e,i)=>{const o=el('option',`重复 ${e.repeat}`);o.value=String(i);rep.append(o);});
const counts=data.counts??{};document.getElementById('status').textContent=`${data.mode==='live_llm'?'真实LLM':'离线夹具'} / ${data.status} · ${counts.attempted_repeats??0}次重复 · 启动${counts.negotiations_started??0}场 / 已结算${counts.terminal_negotiations??0}场 / 失败${counts.failed_or_interrupted??0}项 · ${counts.usage?.calls??0}次调用 / ${(counts.usage?.total_tokens??0).toLocaleString()}个已报告token`;
document.getElementById('statistics').textContent=json({counts:data.counts,statistics:data.statistics});rep.addEventListener('change',reset);method.addEventListener('change',reset);step.addEventListener('input',()=>{selected=tree().nodes[Number(step.value)]?.node_id??'n0';draw();});document.getElementById('play').addEventListener('click',()=>{if(timer){clearInterval(timer);timer=null;return;}step.value='0';selected='n0';draw();timer=setInterval(()=>{if(Number(step.value)>=Number(step.max)){clearInterval(timer);timer=null;return;}step.value=String(Number(step.value)+1);selected=tree().nodes[Number(step.value)].node_id;draw();},900);});if(data.experiments.length)reset();
</script></body></html>'''
